import 'package:flutter/material.dart';
import '../services/api_service.dart';
class NotificationsScreen extends StatefulWidget{const NotificationsScreen({super.key});@override State<NotificationsScreen> createState()=>_NotificationsScreenState();}
class _NotificationsScreenState extends State<NotificationsScreen>{late Future<List<dynamic>> f;@override void initState(){super.initState();f=ApiService.notifications();} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Notifications')),body:FutureBuilder(future:f,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final l=s.data!;if(l.isEmpty)return const Center(child:Text('No notifications yet.'));return ListView.builder(padding:const EdgeInsets.all(12),itemCount:l.length,itemBuilder:(c,i){final n=l[i];return Card(child:ListTile(onTap:()async{await ApiService.markNotificationRead(n['id']);},leading:CircleAvatar(backgroundColor:n['is_read']==true?Colors.grey.shade200:const Color(0xFFE6F4F7),child:Icon(Icons.notifications,color:n['is_read']==true?Colors.grey:const Color(0xFF1A5276))),title:Text(n['title']??'',style:TextStyle(fontWeight:n['is_read']==true?FontWeight.normal:FontWeight.bold)),subtitle:Text(n['message']??''),trailing:Text(n['created_at']?.toString().split('T').first??'',style:const TextStyle(fontSize:11,color:Colors.black45))));});}));}
